def choose_move(observation):
    def pt(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def points_from_keys(keys):
        out = []
        for k in keys:
            vals = observation.get(k, [])
            if isinstance(vals, (list, tuple)):
                for p in vals:
                    if isinstance(p, (list, tuple)) and len(p) >= 2:
                        out.append((p[0], p[1]))
        return out

    def first_point(keys):
        for k in keys:
            v = observation.get(k)
            if isinstance(v, (list, tuple)) and len(v) >= 2 and not isinstance(v[0], (list, tuple)):
                return v[0], v[1]
        return None

    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0

    sx, sy = pt(observation.get("self_position", observation.get("agent_position", (0, 0))))
    opp = first_point(("opponent_position", "enemy_position", "enemy", "opponent"))
    if opp is None:
        opp = (sx, sy)
    ox, oy = opp

    obstacles = set(points_from_keys(("obstacles", "walls", "blocked", "rocks", "boulders")))
    resources = points_from_keys(("resources", "food", "pellets", "collectibles", "targets", "items"))
    territory = points_from_keys(("territory", "owned", "control", "claimed", "my_territory", "friendly_territory"))
    enemy_territory = points_from_keys(("enemy_territory", "opponent_territory", "hostile_territory"))
    frontier = points_from_keys(("frontier", "border", "borders", "neutral", "unclaimed"))

    def valid(nx, ny):
        if w and (nx < 0 or nx >= w):
            return False
        if h and (ny < 0 or ny >= h):
            return False
        if (nx, ny) in obstacles:
            return False
        return True

    def man(a, b, c, d):
        return abs(a - c) + abs(b - d)

    moves = ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1))
    opp_dist = man(sx, sy, ox, oy)

    def nearest_dist(x, y, pts):
        best = None
        for px, py in pts:
            d = abs(x - px) + abs(y - py)
            if best is None or d < best:
                best = d
        return best if best is not None else 10**9

    mode = "territory"
    if resources:
        mode = "resource"
    if opp_dist <= 3 and not resources:
        mode = "evade"
    if opp_dist <= 2 and resources:
        mode = "resource_duel"

    best_move = (0, 0)
    best_score = -10**18

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not valid(nx, ny):
            continue

        score = 0
        nd_opp = man(nx, ny, ox, oy)

        if mode == "evade":
            score += nd_opp * 6
            score -= abs(dx) + abs(dy)
            if dx == 0 and dy == 0:
                score -= 1
        elif mode == "resource":
            dr = nearest_dist(nx, ny, resources)
            score += -dr * 8
            score += nd_opp * 2
            if resources and (nx, ny) in resources:
                score += 20
            if territory and (nx, ny) in territory:
                score += 1
            if frontier and (nx, ny) in frontier:
                score += 2
        elif mode == "resource_duel":
            dr = nearest_dist(nx, ny, resources)
            score += -dr * 7
            score += nd_opp * 4
            if resources and (nx, ny) in resources:
                score += 18
            score -= abs(dx) + abs(dy)
        else:
            if territory:
                dmy = nearest_dist(nx, ny, territory)
                score += -dmy * 4
            if enemy_territory:
                dfoe = nearest_dist(nx, ny, enemy_territory)
                score += -dfoe * 3
            if frontier:
                df = nearest_dist(nx, ny, frontier)
                score += -df * 2
            score += nd_opp * 1
            score -= abs(dx) + abs(dy)
            if (nx, ny) in territory:
                score += 3
            if (nx, ny) in enemy_territory:
