            if dr == 0:
                score += 15
            elif dr == 1:
                score += 4

        if nd_opp <= 1:
            score += 2 if mode != "evade" else -10

        if score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

